//! The teachers' template (`apps/web-2/public/templates/test-template.xlsx`,
//! regenerated by `just server xlsx-template`): one example question of each
//! DOT type on the active sheet and the format on sheet «Инструкция».

use crate::{DotKind, DotOption, DotQuestion, DotTest, WriteError, write::write_template};

fn options(texts: &[&str]) -> Vec<DotOption> {
    texts
        .iter()
        .map(|t| DotOption {
            text: (*t).to_owned(),
            image: None,
        })
        .collect()
}

fn question(text: &str, kind: DotKind) -> DotQuestion {
    DotQuestion {
        row: 0,
        text: text.to_owned(),
        images: Vec::new(),
        level: 0,
        kind,
    }
}

/// The example test of the template.
#[must_use]
pub fn template_test() -> DotTest {
    DotTest {
        title: "Пример теста".into(),
        attempts: 1,
        time_minutes: 30,
        limit: 0,
        leveling: false,
        questions: vec![
            question(
                "Сколько будет 2 + 2?",
                DotKind::Single {
                    options: options(&["3", "4", "5"]),
                    correct: 1,
                },
            ),
            question(
                "Выберите простые числа",
                DotKind::Multiple {
                    options: options(&["2", "4", "5", "9"]),
                    correct: vec![0, 2],
                },
            ),
            question(
                "Столица Казахстана",
                DotKind::Short {
                    answer: "Астана".into(),
                },
            ),
            question(
                "Сопоставьте страну и её столицу",
                DotKind::Matching {
                    left: options(&["Франция", "Япония"]),
                    right: options(&["Париж", "Токио", "Берлин"]),
                    pairs: vec![Some(0), Some(1)],
                },
            ),
            question("Опишите своими словами, что такое алгоритм", DotKind::Essay),
        ],
        images: Vec::new(),
    }
}

const INSTRUCTIONS: &[(&str, &str)] = &[
    (
        "Как пользоваться",
        "Заполните лист Test по образцу и загрузите файл в Ashyq: глава курса → «Добавить» → «Тест из Excel». \
         Файлы тестов из DOT подходят без изменений. Сохраняйте как «Книга Excel (.xlsx)»; .xls не читается.",
    ),
    (
        "Строка 1: настройки",
        "A1 — название теста. B1 не используется. C1 — число попыток (0 — без ограничений, больше 10 станет 10). \
         D1 — время в минутах (0 — без лимита). E1 — сколько вопросов выдавать в попытке (0 — все). \
         F1 — 1, если вопросы распределяются по уровням сложности (столбец D), иначе 0.",
    ),
    (
        "Строки 2 и далее: вопросы",
        "Одна строка — один вопрос. A — текст вопроса (и/или картинка в ячейке). B — тип: 1 один ответ, \
         2 несколько ответов, 3 текстовый ответ, 4 сопоставление, 5 развёрнутый ответ (проверяет преподаватель). \
         C — правильный ответ. D — уровень сложности (только при F1 = 1). E, F, G… — варианты ответа.",
    ),
    (
        "Тип 1 и 2",
        "C — номер правильного варианта, считая от столбца E с единицы: 2 значит второй вариант. \
         Для типа 2 номера через точку с запятой: 1;3. Варианты идут подряд, без пустых ячеек между ними.",
    ),
    (
        "Тип 3",
        "C — правильный ответ. Ответ студента сравнивается без лишних пробелов, числа — по значению, \
         регистр букв учитывается, как в DOT.",
    ),
    (
        "Тип 4",
        "D — сколько элементов слева и справа: 2;3. Варианты: сначала левый столбец, затем правый. \
         C — пары «левый-правый»: 1-1;2-2. Ноль справа (1-0) — у элемента нет пары. \
         Лишние элементы справа ни к чему не подходят и служат для отвлечения.",
    ),
    (
        "Уровни сложности",
        "При F1 = 1 в D ставится уровень: 1, 2, 3 (доли 30/40/30 %), или 101, 102 (по половине), \
         или 201, 202 (две трети и треть). Из каждого уровня выдаётся своя доля вопросов от E1.",
    ),
    (
        "Картинки",
        "Вставьте рисунок в ячейку вопроса или варианта: «Вставка → Рисунок», затем «Поместить в ячейку» \
         или поверх ячейки. Форматы PNG, JPEG, GIF, WebP, до 5 МБ.",
    ),
    (
        "Перенос строки",
        "Перенос строки в ячейке — Alt+Enter. Два символа \\n, как в DOT, тоже станут переносом.",
    ),
];

/// The template workbook.
pub fn template() -> Result<Vec<u8>, WriteError> {
    write_template(&template_test(), INSTRUCTIONS)
}
